import { AdminDeleteUserCommand, AdminGetUserCommand } from "@aws-sdk/client-cognito-identity-provider";
import { DynamoDBClient, GetItemCommand } from '@aws-sdk/client-dynamodb';
import { LambdaClient, InvokeCommand } from '@aws-sdk/client-lambda';

const dynamodb = new DynamoDBClient({ region: process.env.AWS_REGION });
const lambdaClient = new LambdaClient({ region: process.env.AWS_REGION });

export const deleteResData = async (data, cognitoISP, admin, userPoolId, tenantId) => {

    if (!data || !data.id) {
        return {
            id: 0,
        }
    }

    const user = await cognitoISP.send(new AdminGetUserCommand({
        Username: data.id,
        UserPoolId: userPoolId
    }))


    const result = await cognitoISP.send(new AdminDeleteUserCommand({
        Username: data.id,
        UserPoolId: userPoolId,
    }));
    console.log('deleteResData Output:', { httpStatusCode: result?.$metadata?.httpStatusCode });

	const mobileToken = user.UserAttributes.find(attr => attr.Name === "custom:totp-label")?.Value;
    const email = user.UserAttributes.find(attr => attr.Name === "email")?.Value;


    const amfaBody = { email, hasTOTP: Boolean(mobileToken && mobileToken.length > 0), admin, phase: 'admindeleteuser', tenantid: tenantId };

    console.log('admin delete user amfa api body:', { phase: amfaBody.phase, hasTOTP: amfaBody.hasTOTP });

    // W11 (Q26): this call is what removes the user from ASM (login service
    // phase admindeleteuser -> ASM extRemoveUser.kv) and so lowers the billed
    // user count. The Cognito user is already gone, so a failure here is
    // logged at error level for the operator but does not fail the delete.
    // admin* phases are not on the public /amfa route (amfa-442 #1): invoke
    // the login-service function directly with IAM; the tenant is the one the
    // caller was authorized for, never a body field.
    try {
        const res = await lambdaClient.send(new InvokeCommand({
            FunctionName: process.env.AMFA_FUNCTION_ARN,
            Payload: JSON.stringify({
                headers: { Origin: `https://${tenantId}.idapersona.${process.env.AMFA_BASE_URL}` },
                body: JSON.stringify(amfaBody),
            }),
        }));
        if (res.FunctionError) throw new Error(`amfa invoke failed: ${res.FunctionError}`);
        const amfaResponse = JSON.parse(Buffer.from(res.Payload ?? []).toString() || '{}');
        if (amfaResponse.statusCode === 200) {
            console.log(`[ASM-PROPAGATE] admindeleteuser accepted (${amfaResponse.statusCode}) for ${email}`);
        } else {
            console.error(`[ASM-PROPAGATE] admindeleteuser returned ${amfaResponse.statusCode} for ${email}; the user may still exist in ASM`);
        }
    } catch (amfaErr) {
        console.error(`[ASM-PROPAGATE] admindeleteuser call failed for ${email}; the user may still exist in ASM:`, amfaErr.message);
    }

    // Trigger AD user deletion if deleteUserInAdEnabled is configured
    if (tenantId && email && process.env.AD_SYNC_SINGLE_USER_FUNCTION) {
        try {
            const configItem = await dynamodb.send(new GetItemCommand({
                TableName: process.env.CONFIG_TABLE || 'amfa-configtable',
                Key: { id: { S: tenantId }, configtype: { S: 'adSyncConfig' } },
            }));

            const adSyncConfig = configItem.Item?.value?.S ? JSON.parse(configItem.Item.value.S) : null;

            if (adSyncConfig?.enabled && adSyncConfig?.deleteUserInAdEnabled) {
                console.log(`[AD-DELETE] Triggering AD user deletion for: ${email} (tenant: ${tenantId})`);

                await lambdaClient.send(new InvokeCommand({
                    FunctionName: process.env.AD_SYNC_SINGLE_USER_FUNCTION,
                    InvocationType: 'Event', // Async invocation
                    Payload: JSON.stringify({
                        tenantId,
                        username: email,
                        triggerEvent: 'user_deleted',
                    }),
                }));

                console.log(`[AD-DELETE] AD user deletion triggered successfully for: ${email}`);
            }
        } catch (adDeleteErr) {
            // Non-fatal: log error but don't fail the user deletion
            console.error(`[AD-DELETE] Failed to trigger AD user deletion (non-fatal):`, adDeleteErr.message);
        }
    }

    return {
        id: data.id,
    }
}

export default deleteResData;
