import { AdminGetUserCommand } from "@aws-sdk/client-cognito-identity-provider";
import { DynamoDBClient, GetItemCommand } from '@aws-sdk/client-dynamodb';
import { LambdaClient, InvokeCommand } from '@aws-sdk/client-lambda';

const dynamodb = new DynamoDBClient({ region: process.env.AWS_REGION });
const lambdaClient = new LambdaClient({ region: process.env.AWS_REGION });

/**
 * amfa-472: GET /users/{id}?adcheck=1
 *
 * Tells the delete dialog whether the user is a protected admin in the
 * synchronized directory (AD adminCount=1). The sync never deletes such
 * accounts in AD, so deleting them in Cognito alone is undone by the next
 * sync run. Answers { adSyncEnabled, found, isProtected }; every failure
 * degrades to isProtected=false so the dialog still opens.
 */
export const getAdStatus = async (username, cognitoISP, userPoolId, tenantId) => {
    const none = { adSyncEnabled: false, found: false, isProtected: false };
    if (!username || !tenantId || !process.env.AD_SYNC_SINGLE_USER_FUNCTION) return none;

    const configItem = await dynamodb.send(new GetItemCommand({
        TableName: process.env.CONFIG_TABLE || 'amfa-configtable',
        Key: { id: { S: tenantId }, configtype: { S: 'adSyncConfig' } },
    }));
    const adSyncConfig = configItem.Item?.value?.S ? JSON.parse(configItem.Item.value.S) : null;
    if (!adSyncConfig?.enabled) return none;

    const user = await cognitoISP.send(new AdminGetUserCommand({ Username: username, UserPoolId: userPoolId }));
    const email = user.UserAttributes.find(attr => attr.Name === "email")?.Value;
    if (!email) return { ...none, adSyncEnabled: true };

    try {
        const res = await lambdaClient.send(new InvokeCommand({
            FunctionName: process.env.AD_SYNC_SINGLE_USER_FUNCTION,
            InvocationType: 'RequestResponse',
            Payload: JSON.stringify({ tenantId, username: email, triggerEvent: 'check_ad_user' }),
        }));
        const payload = JSON.parse(Buffer.from(res.Payload ?? []).toString() || '{}');
        const body = payload.body || {};
        return { adSyncEnabled: true, found: !!body.found, isProtected: !!body.isProtected };
    } catch (err) {
        console.error(`[AD-CHECK] check_ad_user failed for ${email} (non-fatal):`, err.message);
        return { ...none, adSyncEnabled: true };
    }
};

export default getAdStatus;
